fn put(outp:[*]u8,i:usize,x:i32)void{const bits:u32=@bitCast(x);for(0..4)|k|outp[i*4+k]=@truncate(bits>>(8*k));}
export fn non_preemptive_priority_scheduling(v:[*]const i64,n:usize,outp:[*]u8,cap:usize)i64{if(n<4 or v[0]<1 or v[0]>10 or n!=@as(usize,@intCast(1+3*v[0])))return -1;const count:usize=@intCast(v[0]);var a=[_]i64{0}**10;var b=[_]i64{0}**10;var p=[_]i64{0}**10;var done=[_]bool{false}**10;for(0..count)|i|{const av=v[1+3*i];const bv=v[2+3*i];const pv=v[3+3*i];if(av<0 or av>20 or bv<1 or bv>10 or pv<0 or pv>10)return -1;for(0..i)|j|{if(p[j]==pv)return -1;}a[i]=av;b[i]=bv;p[i]=pv;}if(cap<count*4)return -2;var now:i64=0;var z:usize=0;while(z<count){var pick:?usize=null;for(0..count)|i|{if(!done[i] and a[i]<=now){if(pick==null or p[i]<p[pick.?] or (p[i]==p[pick.?] and a[i]<a[pick.?]))pick=i;}}if(pick==null){var next:i64=100000;for(0..count)|i|{if(!done[i] and a[i]<next)next=a[i];}now=next;continue;}const i=pick.?;done[i]=true;put(outp,z,@intCast(i));z+=1;now+=b[i];}return @intCast(count*4);}
